#!/bin/sh
# Embeds the repo's release_notes_<locale>.txt files into Vialer/Generated/ReleaseNotes.swift so
# the app can show them after an update, like the Flutter ReleaseNotesDialog. Gitignored output.
set -eu

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$ROOT/Vialer/Generated/ReleaseNotes.swift"
mkdir -p "$(dirname "$OUT")"

notes_for() {
    file="$ROOT/../release_notes_$1.txt"
    if [ -f "$file" ]; then
        printf '"""\n%s\n"""' "$(sed 's/\\/\\\\/g; s/"""/\\"""/g' "$file")"
    else
        printf '""'
    fi
}

cat > "$OUT" <<EOF
// Generated by scripts/generate_release_notes.sh from ../release_notes_*.txt. Gitignored; do not edit.
enum ReleaseNotes {
    static let english = $(notes_for en-US)
    static let dutch = $(notes_for nl-NL)
}
EOF
